-- ═══════════════════════════════════════════════════════════════════════════
--  0158 — Khalidiyah's forms, what the tables share: a third identifier on
--         person, the field a file answers, the question map, the file
--         fields, and the rules between fields as data
--
--  GENERATED by supabase/khalidiyah/gen_schema.py from the catalogue.
--
--  ── person.other_id_number ──
--
--  The three ID-type lists (F144, F151, F156) offer "Other ID", and a person
--  with neither a national ID nor a UNHCR number could not be saved
--  (person_has_identifier). A third identifier is added beside the other
--  two: normalised like the UNHCR number, unique, immutable like them
--  (guard_person_national_id, extended from its LIVE body), no format
--  checked -- no source gives one (06_OPEN_QUESTIONS.md). Sahel Horan and
--  Ramtha never write it, and nothing they read changes.
--
--  ── attachment.field_code ──
--
--  A file-upload field (F017 meeting minutes, F120 attendance sheet ...) is
--  evidence on the record, and the row says which field it answers. Null for
--  every attachment outside Khalidiyah. khld_file_field says which fields
--  take files and how many ("5 max"); guard_khld_attachment_field holds an
--  attachment to it. attachment_entity_type_known gains the new tables,
--  appended to its live definition (a name the retired forms already used
--  is not named twice; the retired names stay for the row that names one).
--
--  ── the rules between fields ──
--
--  Every "Dependency" the sheet states ("if F029 = Yes", "if F126 = Held",
--  "if F194 in (Established, Updated)" ...) is one row of khld_field_rule,
--  generated from the catalogue entry the screen reads too: the field is
--  required while its answer is chosen (when the sheet marks it required),
--  and BLANK while it is not -- a stray value on a branch not taken is
--  refused (the lesson of the first forms, KHALIDIYAH_REPORT.md section 7).
--  FORM-19's consent (F158, "if no then end survey") governs every other
--  answer on that form the same way. guard_khld_rules reads the rows for
--  the table it fires on, so the rule lives once, as data; each refusal is
--  named khld_<field>_required / khld_<field>_not_applicable. The three
--  rules that look at another table -- a person registered on the form the
--  sheet names, a partner who confirmed (F174), a market that was held
--  (F207) -- are written out below. The rules a row trigger cannot see (a
--  multi-select or a partner list that must or must not have rows) are
--  checked by save_khld_record after the children are written (0161).
-- ═══════════════════════════════════════════════════════════════════════════

create temp table _0158_attachment_check_before on commit drop as
  select pg_get_constraintdef(oid) as def
    from pg_constraint where conrelid = 'public.attachment'::regclass and conname = 'attachment_entity_type_known';

-- ── 1. person: a third identifier ─────────────────────────────────────────
alter table public.person add column other_id_number text;
alter table public.person add constraint other_id_number_not_blank check (other_id_number is null or btrim(other_id_number) <> '');
alter table public.person drop constraint person_has_identifier;
alter table public.person add constraint person_has_identifier
  check (national_id is not null or unhcr_number is not null or other_id_number is not null);
create unique index person_other_id_number_key on public.person (other_id_number) where other_id_number is not null;
comment on column public.person.other_id_number is
  'An identity document that is neither a Jordanian national ID nor a UNHCR registration '
  '("Other ID", Khalidiyah FORM-12 / -15 / -17). Trimmed, upper-cased, inner spaces '
  'collapsed; no format checked. Unique; immutable once set. 0158.';

create function public.normalise_person_other_id_number()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if new.other_id_number is not null then
    new.other_id_number := nullif(upper(regexp_replace(btrim(new.other_id_number), '\s+', ' ', 'g')), '');
  end if;
  return new;
end $$;
revoke all on function public.normalise_person_other_id_number() from public, anon, authenticated;
create trigger trg_person_other_id_normalise before insert or update of other_id_number on public.person
  for each row execute function public.normalise_person_other_id_number();

-- from its LIVE body (pg_get_functiondef, 26 September 2026), a third branch
create or replace function public.guard_person_national_id()
 returns trigger
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
begin
  if new.national_id is distinct from old.national_id
     and coalesce(public.current_role()::text, 'participant') not in ('coordinator', 'super_admin') then
    raise exception 'national_id cannot be changed';
  end if;
  if new.unhcr_number is distinct from old.unhcr_number
     and coalesce(public.current_role()::text, 'participant') not in ('coordinator', 'super_admin') then
    raise exception 'unhcr_number cannot be changed';
  end if;
  if new.other_id_number is distinct from old.other_id_number
     and coalesce(public.current_role()::text, 'participant') not in ('coordinator', 'super_admin') then
    raise exception 'other_id_number cannot be changed';
  end if;
  return new;
end $function$;

