do $check$
declare
  v_def  text;
  v_add  text := '';
  v_name text;
begin
  select def into v_def from _0158_attachment_check_before;
  if v_def !~ '^CHECK \(\(entity_type = ANY \(ARRAY\[' or v_def !~ '\]\)\)\)$' then
    raise exception '0158: attachment_entity_type_known is not the shape this migration appends to: %', v_def;
  end if;
  foreach v_name in array array['khld_focal_point', 'khld_partner', 'khld_partner_contact', 'khld_meeting', 'khld_rehab_report', 'khld_campaign', 'khld_activity', 'khld_activity_attendance', 'khld_committee_member', 'khld_committee_meeting', 'khld_volunteer', 'khld_volunteer_attendance', 'khld_guidance_session', 'khld_enterprise_request', 'khld_market', 'khld_vendor_application', 'khld_market_attendance', 'khld_park_survey', 'khld_partner_survey', 'khld_contribution', 'khld_milestone_record', 'khld_enterprise_support', 'khld_producer_survey'] loop
    if position(format('''%s''::text', v_name) in v_def) = 0 then
      v_add := v_add || format(', %L::text', v_name);
    end if;
  end loop;
  v_def := regexp_replace(v_def, '\]\)\)\)$', v_add || '])))');
  execute 'alter table public.attachment drop constraint attachment_entity_type_known';
  execute 'alter table public.attachment add constraint attachment_entity_type_known ' || v_def;
end $check$;

