create function public.guard_khld_attachment_field()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_max int;
  v_n   int;
begin
  if new.field_code is null or new.deleted_at is not null then
    return new;
  end if;
  select f.max_files into v_max from public.khld_file_field f
   where f.table_name = new.entity_type and f.field_code = new.field_code;
  if v_max is null then
    raise exception '% is not a file field of %', new.field_code, new.entity_type
      using errcode = 'check_violation', constraint = 'attachment_field_code_known';
  end if;
  select count(*) into v_n from public.attachment a
   where a.entity_type = new.entity_type and a.entity_id = new.entity_id and a.field_code = new.field_code
     and a.deleted_at is null and a.id <> new.id;
  if v_n >= v_max then
    raise exception '% takes at most % files', new.field_code, v_max
      using errcode = 'check_violation', constraint = 'attachment_field_code_max_files';
  end if;
  return new;
end $$;
revoke all on function public.guard_khld_attachment_field() from public, anon, authenticated;
create trigger trg_attachment_khld_field before insert or update of field_code, deleted_at on public.attachment
  for each row execute function public.guard_khld_attachment_field();

