-- Do the conditions of a rule hold for a row? An unanswered governing
-- answer means "not chosen": the field it governs must then be blank.
create function public.khld_rule_on(p_row jsonb, p_conditions jsonb)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  c      jsonb;
  v_code text;
begin
  for c in select value from jsonb_array_elements(p_conditions) loop
    if c ? 'list' then
      v_code := null;
      if p_row ->> (c ->> 'column') is not null then
        execute format('select code from public.%I where id = $1', 'ref_khld_' || (c ->> 'list'))
          into v_code using (p_row ->> (c ->> 'column'))::uuid;
      end if;
      if not coalesce(v_code in (select jsonb_array_elements_text(c -> 'codes')), false) then
        return false;
      end if;
    elsif c ? 'bool' then
      if not coalesce((p_row ->> (c ->> 'column'))::boolean = (c ->> 'bool')::boolean, false) then
        return false;
      end if;
    elsif (p_row ->> (c ->> 'column')) is null then
      return false;
    end if;
  end loop;
  return true;
end $$;
revoke all on function public.khld_rule_on(jsonb, jsonb) from public, anon;
grant execute on function public.khld_rule_on(jsonb, jsonb) to authenticated;

create function public.guard_khld_rules()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_row  jsonb := to_jsonb(new);
  r      record;
  v_on   boolean;
begin
  for r in select * from public.khld_field_rule
            where table_name = tg_table_name and column_name !~ ':' and column_name <> 'partners' loop
    v_on := public.khld_rule_on(v_row, r.conditions);
    if v_on and r.required and (v_row ->> r.column_name) is null then
      raise exception '% is required when %', r.field_code, r.when_text
        using errcode = 'check_violation', constraint = 'khld_' || lower(r.field_code) || '_required';
    end if;
    if not v_on and (v_row ->> r.column_name) is not null then
      raise exception '% belongs to the answer "%", which is not chosen, so it must be blank', r.field_code, r.when_text
        using errcode = 'check_violation', constraint = 'khld_' || lower(r.field_code) || '_not_applicable';
    end if;
  end loop;

  -- The four rules that look at another table. Each reads NEW's columns
  -- inside its own table's branch: PL/pgSQL prepares a whole condition, so a
  -- column another table does not have may not appear in a test that fires
  -- on it, even behind a false tg_table_name.
  if tg_table_name in ('khld_market_attendance', 'khld_producer_survey') then
    -- F112 / F206: a vendor registered on FORM-17
    if not exists (select 1 from public.khld_vendor_application s
                    where s.person_id = new.person_id and s.municipality_id = new.municipality_id and s.deleted_at is null) then
      raise exception '%: the person must be registered on FORM-17', case tg_table_name when 'khld_market_attendance' then 'F112' else 'F206' end
        using errcode = 'check_violation', constraint = 'khld_person_registered';
    end if;
  end if;
  if tg_table_name = 'khld_enterprise_support' then
    -- F197: an owner who asked on FORM-15
    if not exists (select 1 from public.khld_enterprise_request s
                    where s.person_id = new.person_id and s.municipality_id = new.municipality_id and s.deleted_at is null) then
      raise exception 'F197: the enterprise owner must have an attendance request on FORM-15'
        using errcode = 'check_violation', constraint = 'khld_person_registered';
    end if;
  end if;
  if tg_table_name = 'khld_partner_survey' then
    -- F174: "prepopulated <F004> where F116 = Yes"
    if not exists (select 1 from public.khld_partner_contact c
                    where c.partner_id = new.partner_id and c.partnership_confirmed and c.deleted_at is null) then
      raise exception 'F174: the partner must have confirmed the partnership (FORM-04 F116 = Yes)'
        using errcode = 'check_violation', constraint = 'khld_f174_confirmed_partner';
    end if;
  end if;
  if tg_table_name = 'khld_producer_survey' then
    -- F207: "prepopulated FORM-16 <F091> where F154 = Held"
    if not exists (select 1 from public.khld_market k join public.ref_khld_event_status s on s.id = k.status_id
                    where k.id = new.market_id and s.code = 'held' and k.deleted_at is null) then
      raise exception 'F207: the market must be one that was held (FORM-16 F154 = Held)'
        using errcode = 'check_violation', constraint = 'khld_f207_market_held';
    end if;
  end if;
  return new;
end $$;
revoke all on function public.guard_khld_rules() from public, anon, authenticated;
comment on function public.guard_khld_rules() is
  'BEFORE INSERT OR UPDATE on the Khalidiyah tables: the khld_field_rule rows of the table, '
  'and the four rules that look at another table. 0158.';

-- ── 5. the review of a public volunteer registration, stamped ─────────────
create function public.khld_stamp_review()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if new.application_status is distinct from old.application_status then
    new.reviewed_by := auth.uid();
    new.reviewed_on := now();
  end if;
  return new;
end $$;
revoke all on function public.khld_stamp_review() from public, anon, authenticated;

-- ── verification ─────────────────────────────────────────────────────────
do $verify$
declare
  v_old text;
  v_new text;
  v_name text;
begin
  -- the attachment check kept every table it named, in order, and names the new ones
  select def into v_old from _0158_attachment_check_before;
  select pg_get_constraintdef(oid) into v_new from pg_constraint
   where conrelid = 'public.attachment'::regclass and conname = 'attachment_entity_type_known';
  if position(regexp_replace(v_old, '\]\)\)\)$', '') in v_new) <> 1 then
    raise exception '0158: the attachment check was not appended to: %', v_new;
  end if;
  foreach v_name in array array['khld_focal_point', 'khld_partner', 'khld_partner_contact', 'khld_meeting', 'khld_rehab_report', 'khld_campaign', 'khld_activity', 'khld_activity_attendance', 'khld_committee_member', 'khld_committee_meeting', 'khld_volunteer', 'khld_volunteer_attendance', 'khld_guidance_session', 'khld_enterprise_request', 'khld_market', 'khld_vendor_application', 'khld_market_attendance', 'khld_park_survey', 'khld_partner_survey', 'khld_contribution', 'khld_milestone_record', 'khld_enterprise_support', 'khld_producer_survey'] loop
    if position(format('''%s''::text', v_name) in v_new) = 0 then
      raise exception '0158: the attachment check does not name %', v_name;
    end if;
  end loop;
  -- a person with an other ID alone can be saved and is normalised; one with none cannot
  begin
    insert into public.person (full_name, other_id_number, date_of_birth) values ('0158 probe', ' ab  12 ', '1990-01-01');
    if not exists (select 1 from public.person where other_id_number = 'AB 12') then
      raise exception '0158: other_id_number was not normalised';
    end if;
    raise exception using errcode = 'P0158', message = 'rollback';
  exception when sqlstate 'P0158' then null;
  end;
  begin
    insert into public.person (full_name, date_of_birth) values ('0158 probe', '1990-01-01');
    raise exception '0158: a person with no identifier was saved';
  exception when check_violation then
    if sqlerrm !~ 'person_has_identifier' then raise; end if;
  end;
  if exists (select 1 from public.person where full_name = '0158 probe') then
    raise exception '0158: probe rows survived the rollback';
  end if;
  if (select count(*) from public.khld_field_rule) <> 36 or (select count(*) from public.khld_file_field) <> 9
     or (select count(*) from public.khld_question_list) <> 10 then
    raise exception '0158: the rule, file-field or question rows are not the catalogue''s';
  end if;
end $verify$;
